                                                                                                                        '{"precipitation_forecast": "20mm", "farm_decisions": ["postpone_fertilizer", "skip_irrigation", "delay_pesticide"], "timing": "weather_based_planning"}'
                                                                                                                        ),( 'real-nasa-application'
