-- Update question counts for all new quizzes
update public.quizzes
   set
   questions_count = (
      select count(*)
        from public.quiz_questions
       where quiz_id = 'harvestia-nasa-features'
   )
 where id = 'harvestia-nasa-features';

update public.quizzes
   set
   questions_count = (
      select count(*)
        from public.quiz_questions
       where quiz_id = 'real-nasa-application'
   )
 where id = 'real-nasa-application';

update public.quizzes
   set
   questions_count = (
      select count(*)
        from public.quiz_questions
       where quiz_id = 'nasa-data-interpretation'
   )
 where id = 'nasa-data-interpretation';

-- Final summary
select 'Harvestia NASA Data Quizzes Created Successfully!' as result,
       (
          select count(*)
            from public.quizzes
           where id like '%nasa%'
              or id like '%harvestia%'
       ) as app_related_quizzes,
       (
          select count(*)
            from public.quiz_questions
           where quiz_id like '%nasa%'
              or quiz_id like '%harvestia%'
       ) as total_questions;